import Base
def duplicate(-C: Type,values: List<C>) -> List<C> & List<C>:
  (values,values)

import Base
import ./types.bend as T
def write(-Owner: Type,set: Owner -> T.PositionToken -> U32 -> Owner,owner: Owner) -> Owner:
  set(owner,T.PositionToken{},9)
def forbidden(-Owner: Type,get: Owner -> T.PositionToken -> Owner & T.Access<T.PositionView>,owner: Owner) -> Owner:
  write(Owner,get,owner)
